import java.util.ArrayList;
import java.util.List;

class RecordingPriceListener implements PriceListener {
    final List<String> seen = new ArrayList<>();

    @Override
    public void priceChanged(String symbol, int oldPrice, int newPrice) {
        seen.add(symbol + ":" + oldPrice + "->" + newPrice);
    }

    String log() {
        return String.join(",", seen);
    }
}

class SelfRemovingPriceListener implements PriceListener {
    private final PriceAlertHub hub;
    int calls = 0;

    SelfRemovingPriceListener(PriceAlertHub hub) {
        this.hub = hub;
    }

    @Override
    public void priceChanged(String symbol, int oldPrice, int newPrice) {
        calls++;
        hub.removePriceListener(this);
    }
}

public class PriceAlertHubTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            PriceAlertHub hub = new PriceAlertHub();
            RecordingPriceListener first = new RecordingPriceListener();
            RecordingPriceListener second = new RecordingPriceListener();

            check("no listeners at the start", 0, hub.listenerCount());
            check("unknown symbol is worth 0", 0, hub.getPrice("ACME"));

            hub.addPriceListener(first);
            hub.addPriceListener(second);
            check("two listeners registered", 2, hub.listenerCount());

            hub.setPrice("ACME", 10);
            check("stored price", 10, hub.getPrice("ACME"));
            check("first listener heard the change", "ACME:0->10", first.log());
            check("second listener heard it too", "ACME:0->10", second.log());

            hub.setPrice("ACME", 10);
            check("an unchanged price notifies nobody", "ACME:0->10", first.log());

            hub.removePriceListener(second);
            hub.setPrice("ACME", 12);
            check("one listener left", 1, hub.listenerCount());
            check("remaining listener sees the old price",
                    "ACME:0->10,ACME:10->12", first.log());
            check("removed listener is silent", "ACME:0->10", second.log());

            PriceAlertHub second_hub = new PriceAlertHub();
            SelfRemovingPriceListener quitter = new SelfRemovingPriceListener(second_hub);
            second_hub.addPriceListener(quitter);
            try {
                second_hub.setPrice("ZED", 5);
                check("a listener may unsubscribe while being notified", 1, quitter.calls);
                check("it really is gone", 0, second_hub.listenerCount());
            } catch (Throwable inner) {
                System.out.println("FAIL  notifying from a copy -- " + inner);
                failures++;
            }
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

