import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

interface PriceListener {
    void priceChanged(String symbol, int oldPrice, int newPrice);
}

public class PriceAlertHub {

    private final List<PriceListener> listeners = new ArrayList<>();
    private final Map<String, Integer> prices = new HashMap<>();

    public void addPriceListener(PriceListener listener) {
        listeners.add(listener);
    }

    public void removePriceListener(PriceListener listener) {
        listeners.remove(listener);
    }

    public int listenerCount() {
        return listeners.size();
    }

    public int getPrice(String symbol) {
        Integer stored = prices.get(symbol);
        return stored == null ? 0 : stored;
    }

    public void setPrice(String symbol, int newPrice) {
        int oldPrice = getPrice(symbol);
        if (oldPrice == newPrice) {
            return;
        }
        prices.put(symbol, newPrice);
        for (PriceListener listener : new ArrayList<>(listeners)) {
            listener.priceChanged(symbol, oldPrice, newPrice);
        }
    }
}
